package com.nicole.nudge;
import android.app.job.*;import android.content.*;import java.io.*;import java.net.*;
public class BackupJob extends JobService {
 static void schedule(Context context){if(!new File(context.getFilesDir(),"encrypted-backup.json").exists())return;JobScheduler scheduler=(JobScheduler)context.getSystemService(JOB_SCHEDULER_SERVICE);scheduler.schedule(new JobInfo.Builder(101,new ComponentName(context,BackupJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPersisted(true).setPeriodic(6L*3600000L).build());}
 @Override public boolean onStartJob(JobParameters params){new Thread(()->{boolean retry=false;try{File file=new File(getFilesDir(),"encrypted-backup.json");String token=getSharedPreferences("nudge",0).getString("backupToken","");if(!file.exists()||token.isEmpty()){jobFinished(params,false);return;}HttpURLConnection c=(HttpURLConnection)new URL(MainActivity.API+"/api/backup").openConnection();c.setRequestMethod("POST");c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("X-Nudge-Encryption","AES-256-GCM");c.setDoOutput(true);c.setFixedLengthStreamingMode(file.length());try(InputStream in=new FileInputStream(file);OutputStream out=c.getOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}retry=c.getResponseCode()/100!=2;c.disconnect();}catch(Exception e){retry=true;}jobFinished(params,retry);}).start();return true;}
 @Override public boolean onStopJob(JobParameters params){return true;}
}
